INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Kilobyte immer genau 1000 Byte?', 2, '[{"text": "Nein", "correct": true, "because": "In IT oft 1024 Byte"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit SI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Präfix steht für eine Million?', 3, '[{"text": "Mega", "correct": true, "because": "10^6 oder ca. 2^20"}, {"text": "Kilo", "correct": false, "because": "10^3"}, {"text": "Giga", "correct": false, "because": "10^9"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixe nutzt man für Speichergrößen?', 5, '[{"text": "Kilo", "correct": true, "because": "Für KB"}, {"text": "Tera", "correct": true, "because": "Für TB"}, {"text": "Zenti", "correct": false, "because": "Nicht in IT"}, {"text": "Milli", "correct": false, "because": "Zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Giga bedeutet 10^9. b) In IT ist es immer exakt 1000^3.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IT nutzt 1024^3"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Berechnung von Speichergrößen?', 4, '[{"text": "Basis 1024", "correct": false, "because": "IT-Standard"}, {"text": "Präfixe wie Mega", "correct": false, "because": "Wichtig für Größen"}, {"text": "Farbe der Festplatte", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Terabyte genau 1000 Gigabyte ist?', 2, '[{"text": "Nein", "correct": true, "because": "In IT 1024 GB"}, {"text": "Ja", "correct": false, "because": "SI vs. Binär"}]'),
(' incess_fk, text, points, options) VALUES0000-0000-00000000', 'Welcher Präfix steht für 10^12?', 3, '[{"text": "Tera", "correct": true, "because": "Dezimalpräfix für Billion"}, {"text": "Peta", "correct": false, "because": "10^15"}, {"text": "Giga", "correct": false, "because": "10^9"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte repräsentieren diese Präfixe in IT?', 5, '[{"text": "Mega = 2^20", "correct": true, "because": "Ca. 1 Million"}, {"text": "Giga = 2^30", "correct": true, "because": "Ca. 1 Milliarde"}, {"text": "Kilo = 1000", "correct": false, "because": "In IT 1024"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Präfixe in IT sind binärbasiert. b) Sie sind immer dezimal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IT nutzt 1024"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Speicher mit Präfixen zu berechnen?', 4, '[{"text": "Basis 1024", "correct": false, "because": "IT-Standard"}, {"text": "Präfix-Reihenfolge", "correct": false, "because": "Kilo, Mega, etc."}, {"text": "CPU-Takt", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Megabyte 1000 Kilobyte?', 2, '[{"text": "Nein", "correct": true, "because": "In IT 1024 KB"}, {"text": "Ja", "correct": false, "because": "SI vs. Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Präfixe sind für große Speicher relevant?', 4, '[{"text": "Tera", "correct": true, "because": "Für TB"}, {"text": "Peta", "correct": true, "because": "Für PB"}, {"text": "Milli", "correct": false, "because": "Zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Gigabyte genau 1000 Megabyte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "In IT 1024 MB"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit SI"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Präfixen in IT?', 3, '[{"text": "Binärbasis 1024", "correct": true, "because": "IT-Standard"}, {"text": "Dezimalbasis 1000", "correct": false, "because": "SI, nicht IT"}, {"text": "Einfache Namen", "correct": false, "because": "Technische Korrektheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Peta ist 10^15. b) In IT ist es 1000^5.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "IT nutzt 1024^5"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheiten nutze ich für Festplattengrößen?', 5, '[{"text": "Gigabyte", "correct": true, "because": "Häufige Größe"}, {"text": "Terabyte", "correct": true, "because": "Für große Speicher"}, {"text": "Bit", "correct": false, "because": "Zu klein"}, {"text": "Dekagramm", "correct": false, "because": "Keine IT-Einheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Dezimalpräfixen in IT unwichtig?', 3, '[{"text": "Umrechnung mit 1024", "correct": false, "because": "IT-Standard"}, {"text": "Reihenfolge der Präfixe", "correct": false, "because": "Logische Struktur"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Petabyte 1000 Terabyte?', 3, '[{"text": "Nein", "correct": true, "because": "In IT 1024 TB"}, {"text": "Ja", "correct": false, "because": "SI vs. Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kilo in IT immer 1000 bedeutet?', 2, '[{"text": "Nein", "correct": true, "because": "In IT 1024"}, {"text": "Ja", "correct": false, "because": "Verwechslung mit SI"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Präfix ist der größte in der IT-Nutzung?', 4, '[{"text": "Peta", "correct": true, "because": "2^50, sehr groß"}, {"text": "Tera", "correct": false, "because": "Kleiner als Peta"}, {"text": "Giga", "correct": false, "because": "Noch kleiner"}]');
